import math

def dot_product(v1, v2):
    return sum(a * b for a, b in zip(v1, v2))

def magnitude(v):
    return math.sqrt(sum(a * a for a in v))

def cosine_similarity(v1, v2):
    # angle versus magnitude
    return dot_product(v1, v2) / (magnitude(v1) * magnitude(v2))

def normalize(v):
    # scales a vector to a fixed length
    m = magnitude(v)
    return [x / m for x in v]

vec_a = [1, 2, 3]
vec_b = [10, 20, 30]  # same direction as vec_a, much larger magnitude

print("Unnormalized vectors:")
print(f"  dot product: {dot_product(vec_a, vec_b):.2f}")
print(f"  cosine similarity: {cosine_similarity(vec_a, vec_b):.2f}\n")

norm_a, norm_b = normalize(vec_a), normalize(vec_b)
print("Normalized vectors:")
print(f"  dot product: {dot_product(norm_a, norm_b):.2f}")
print(f"  cosine similarity: {cosine_similarity(norm_a, norm_b):.2f}")
print("\nOn normalized vectors, dot product and cosine similarity agree.")
